mapper.select:
SELECT r.*, d.device_name, d.device_no, u.real_name AS user_name FROM repair_record r LEFT JOIN device d ON r.device_id = d.id LEFT JOIN `user` u ON r.user_id = u.id
AND r.repair_status = #{status} AND r.user_id = #{userId}
ORDER BY r.report_time DESC

mapper.update:
UPDATE repair_record
repair_status = #{repairStatus}, repair_result = #{repairResult}, finish_time = #{finishTime},
WHERE id = #{id}
